constexpr std::array<std::string_view, 1> kKitReasoning{{
    R"KIT(name: reasoning
description: Solve arithmetic and logic problems with a correct final answer.
skill: reasoning

synth:
  system: |
    You produce supervised fine-tuning examples that teach a small language model
    to reason through arithmetic and simple logic problems and state a correct
    final answer. Each example pairs a user prompt — a self-contained word problem
    or arithmetic/logic question with a single unambiguous answer — with an
    assistant completion that works through the steps briefly and ends with the
    correct final answer clearly stated (e.g. on a final line "Answer: 150").
    The final answer MUST be correct. Vary the problem types: percentages, rates
    and distances, ratios, basic algebra, counting, unit conversions, and short
    deductive-logic puzzles. Keep numbers clean so the answer is exact.
  seeds:
    - "percentage problems (e.g. 'what is X% of Y')"
    - "rate / distance / time word problems"
    - "ratio and proportion problems"
    - "basic single-variable algebra"
    - "counting and combinatorics (small numbers)"
    - "unit conversion problems"
    - "sequence / pattern next-term problems"
    - "short deductive logic puzzles with a definite answer"
  count: 200
  per_seed: 8
  temperature: 0.7

train:
  iters: 500
  num_layers: 16

eval:
  - prompt: "What is 15% of 240?"
    expected: "36"
  - prompt: "If a train travels at 60 mph for 2.5 hours, how far does it go? Give the number of miles."
    expected: "150"
  - prompt: "What is the square root of 144?"
    expected: "12"
  - prompt: "A shirt costs $40 and is discounted by 25%. What is the sale price in dollars?"
    expected: "30"
  - prompt: "If 3x = 21, what is x?"
    expected: "7"
  - prompt: "How many minutes are there in 3 hours?"
    expected: "180"
  - prompt: "What is the next number in the sequence 2, 4, 8, 16, ...?"
    expected: "32"
  - prompt: "A basket has 5 apples and you add 7 more, then remove 3. How many apples are there?"
    expected: "9"
  - prompt: "What is 12 multiplied by 13?"
    expected: "156"
  - prompt: "A book has 320 pages and you read 40 pages a day. How many days to finish it?"
    expected: "8"
  - prompt: "What is 20% of 85?"
    expected: "17"
  - prompt: "If 5y - 3 = 22, what is y?"
    expected: "5"
  - prompt: "How many seconds are there in 4 minutes?"
    expected: "240"
  - prompt: "A rectangle is 7 cm wide and 9 cm long. What is its area in square centimeters?"
    expected: "63"
  - prompt: "What is the next number in the sequence 3, 6, 9, 12, ...?"
    expected: "15"
  - prompt: "Tickets cost $12 each. How much do 7 tickets cost in dollars?"
    expected: "84"
  - prompt: "A car uses 6 liters of fuel per 100 km. How many liters for 250 km?"
    expected: "15"
  - prompt: "What is 1000 divided by 8?"
    expected: "125"
  - prompt: "If today is Monday, what day of the week is it 10 days from now?"
    expected: "Thursday"
  - prompt: "A class has 18 girls and 12 boys. What fraction of the class are boys, as a percentage?"
    expected: "40"
  - prompt: "What is the sum of the angles in a triangle, in degrees?"
    expected: "180"
  - prompt: "You buy 3 notebooks at $4 each and pay with a $20 bill. How much change do you get in dollars?"
    expected: "8"
  - prompt: "What is 2 to the power of 10?"
    expected: "1024"
  - prompt: "A recipe needs 3 eggs for 12 cookies. How many eggs for 36 cookies?"
    expected: "9"
)KIT",
}};

const std::string& kit_reasoning() {
    static const std::string text = join(kKitReasoning);
    return text;
}

constexpr std::array<std::string_view, 1> kKitStructuredOutput{{
    R"KIT(name: structured-output
description: Emit well-formed JSON that matches a requested shape.
skill: structured-output

synth:
  system: |
    You produce supervised fine-tuning examples that teach a small language model
    to return well-formed, minimal JSON. Each example pairs a user prompt that asks
    for information "as JSON" with a named set of fields, and an assistant
    completion that is ONLY a single valid JSON object (or array) with exactly the
    requested fields — no prose, no markdown fences, no trailing commentary. Keys
    must match what the user asked for. Values must be plausible and correctly
    typed (strings quoted, numbers bare, booleans lowercase). Vary the domains
    (people, products, geography, events, configuration) and the field sets.
  seeds:
    - "object with fields: name (string), age (number)"
    - "object describing a city: city, country, population (number)"
    - "object with a boolean flag and a short reason string"
    - "array of 3 objects, each {id, label}"
    - "object with nested object (e.g. address with city and zip)"
    - "object representing a product: name, price (number), in_stock (boolean)"
    - "object with an array field (e.g. tags: [..])"
    - "configuration object with mixed types"
  count: 200
  per_seed: 8
  temperature: 0.8

train:
  iters: 400
  num_layers: 16

eval:
  - prompt: "Return JSON with a single field \"status\" set to the string \"ok\". JSON only."
    expected: "\"status\""
  - prompt: "Give me a JSON object with field \"count\" set to the number 5. JSON only, no markdown."
    expected: "\"count\""
  - prompt: "Return a JSON object describing France with fields \"country\" and \"capital\". JSON only."
    expected: "\"capital\""
  - prompt: "Return JSON with a boolean field \"enabled\" set to true. JSON only."
    expected: "true"
  - prompt: "Return a JSON object with field \"name\" set to \"Ada\". JSON only."
    expected: "\"name\""
  - prompt: "Return a JSON array containing the three strings \"a\", \"b\", \"c\". JSON only."
    expected: "["
  - prompt: "Return JSON with field \"price\" set to the number 19. JSON only."
    expected: "\"price\""
  - prompt: "Return a JSON object with field \"ok\" set to the boolean false. JSON only."
    expected: "false"
  - prompt: "Return JSON with a field \"city\" set to the string \"Lima\". JSON only."
    expected: "\"city\""
  - prompt: "Return a JSON object with an integer field \"age\" set to 30. JSON only, no markdown."
    expected: "\"age\""
  - prompt: "Return a JSON object with fields \"first\" and \"last\" for the name Grace Hopper. JSON only."
    expected: "\"last\""
  - prompt: "Return a JSON array of the numbers 1, 2 and 3. JSON only."
    expected: "1"
  - prompt: "Return JSON with a field \"tags\" holding an array of the strings \"x\" and \"y\". JSON only."
    expected: "\"tags\""
  - prompt: "Return a JSON object with a field \"active\" set to the boolean true and a field \"id\" set to 7. JSON only."
    expected: "\"active\""
  - prompt: "Return a JSON object with a field \"items\" set to an empty array. JSON only."
    expected: "\"items\""
  - prompt: "Return JSON describing a book with fields \"title\" and \"year\". JSON only."
    expected: "\"year\""
  - prompt: "Return JSON with a field \"note\" set to null. JSON only."
    expected: "null"
  - prompt: "Return a JSON object with a nested object \"owner\" that has a field \"name\". JSON only."
    expected: "\"owner\""
  - prompt: "Return JSON with a field \"ratio\" set to the number 0.5. JSON only."
    expected: "\"ratio\""
  - prompt: "Return a JSON object with a field \"unit\" set to the string \"kg\". JSON only."
    expected: "\"kg\""
  - prompt: "Return a JSON array of two objects, each with a field \"n\". JSON only."
    expected: "\"n\""
  - prompt: "Return JSON with a field \"version\" set to the string \"1.2.0\". JSON only."
    expected: "\"1.2.0\""
  - prompt: "Return a JSON object with a field \"done\" set to false and a field \"steps\" set to 3. JSON only."
    expected: "\"steps\""
  - prompt: "Return JSON with a field \"email\" set to \"ada@example.com\". JSON only."
    expected: "\"email\""
)KIT",
}};

