constexpr std::array<std::string_view, 2> kScriptPrepareDatasetPy{{
    R"PY(#!/usr/bin/env python3
"""Dataset preparation driver for Apogee.

Converts a local data file (JSONL / JSON / CSV / Parquet) -- or a downloaded
dataset directory holding such files -- into trainer-ready JSONL. Apogee never
reaches the Hugging Face Hub from here: sources are local files only.

JSON, JSONL and CSV are read with the standard library, so the common path
needs nothing installed. Parquet needs the `datasets` library
(`apogee train setup --with prepare`), and it is imported only for Parquet.

Output formats:
  Default (chat):  {"messages": [{"role": "user", ...}, {"role": "assistant", ...}]}
  --flat:          {"prompt": "...", "completion": "..."}
  --as-eval:       {"prompt": "...", "expected": "..."}  (an eval suite)

Emits JSONL progress lines to stdout -- the protocol every Apogee training
script speaks:
  {"message": "..."}
  {"rows_written": N, "rows_skipped": N, "out": "path"}
  {"error": "..."}   <- fatal; a non-zero exit follows
"""

import sys
import json
import argparse
import os
import csv

# Environment guards, BEFORE any ML import. Skipping them causes silent
# SIGABRT crashes that mask the real error.
#
# Must be set before `datasets` imports its Rust tokenizer extension, which
# spawns fork-based workers that can deadlock on macOS.
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")

# Apogee never reaches the Hugging Face Hub from a script -- force the
# libraries offline so they can only ever read the local file named here.
os.environ["HF_HUB_OFFLINE"] = "1"
os.environ["HF_DATASETS_OFFLINE"] = "1"
os.environ["HF_HUB_DISABLE_TELEMETRY"] = "1"


def emit(obj):
    print(json.dumps(obj), flush=True)


def fail(message):
    emit({"error": message})
    sys.exit(1)


# -- format detection ---------------------------------------------------------

def detect_format(columns):
    """Infer a format preset from column names. Returns the preset or None."""
    col_set = set(columns)
    if "instruction" in col_set and "output" in col_set:
        return "alpaca"
    if "conversations" in col_set:
        return "sharegpt"
    if "role" in col_set and "text" in col_set:
        return "oasst"
    if "prompt" in col_set and "completion" in col_set:
        return "prompt-completion"
    if "messages" in col_set:
        return "chatml"
    return None


# -- row converters ------------------------------------------------------------

def _text(value):
    """A cell as text: None becomes empty, everything else is stringified."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    return json.dumps(value)


def make_messages_alpaca(row, col_map):
    """Alpaca: instruction[+input] -> user, output -> assistant (chat format)."""
    instruction = _text(row.get(col_map.get("instruction", "instruction"), ""))
    inp = _text(row.get(col_map.get("input", "input"), ""))
    output = _text(row.get(col_map.get("output", "output")) or
                   row.get(col_map.get("completion", "completion"), ""))
    if not instruction or not output:
        return None
    content = "%s\n\n%s" % (instruction, inp) if inp else instruction
    return {"messages": [
        {"role": "user", "content": content},
        {"role": "assistant", "content": output},
    ]}


def make_flat_alpaca(row, col_map):
    """Alpaca: instruction[+input] -> prompt, output -> completion (flat)."""
    result = make_messages_alpaca(row, col_map)
    if result is None:
        return None
    return {"prompt": result["messages"][0]["content"],
            "completion": result["messages"][1]["content"]}


def _conversation(value):
    """A conversations cell as a list -- CSV carries it as a JSON string."""
    if isinstance(value, str):
        value = value.strip()
        if not value.startswith("["):
            return None
        try:
            value = json.loads(value)
        except ValueError:
            return None
    return value if isinstance(value, list) else None


def make_messages_sharegpt(row, col_map):
    """ShareGPT/ChatML: a conversations list -> messages (chat format).

    Accepts both ShareGPT ("from"/"value") and ChatML ("role"/"content")
    item shapes. Role mapping: human->user, gpt->assistant.
    """
    conv_col = col_map.get("conversations", "conversations")
    conv = _conversation(row.get(conv_col))
    if conv is None:
        conv = _conversation(row.get(col_map.get("messages", "messages")))
    if not conv:
        return None
    role_map = {
        "human": "user", "gpt": "assistant", "system": "system",
        "user": "user", "assistant": "assistant",
    }
    messages = []
    for item in conv:
        if not isinstance(item, dict):
            continue
        role = item.get("from") or item.get("role", "")
        content = item.get("value") or item.get("content", "")
        role = role_map.get(role, role)
        if role and content:
            messages.append({"role": role, "content": _text(content)})
    return {"messages": messages} if messages else None


def make_flat_sharegpt(row, col_map):
    """ShareGPT/ChatML: the last user->assistant pair as prompt/completion."""
    result = make_messages_sharegpt(row, col_map)
    if result is None:
        return None
    user_content = ""
    assistant_content = ""
    for m in result["messages"]:
        if m["role"] == "user":
            user_content = m["content"]
        elif m["role"] == "assistant" and user_content:
            assistant_content = m["content"]
    if not user_content or not assistant_content:
        return None
    return {"prompt": user_content, "completion": assistant_content}


def make_messages_prompt_completion(row, col_map):
    """Passthrough: prompt + completion columns, wrapped in chat format."""
    prompt = _text(row.get(col_map.get("prompt", "prompt"), ""))
    completion = _text(row.get(col_map.get("completion", "completion"), ""))
    if not prompt or not completion:
        return None
    return {"messages": [
        {"role": "user", "content": prompt},
        {"role": "assistant", "content": completion},
    ]}


def make_flat_prompt_completion(row, col_map):
    """Passthrough: prompt + completion columns (flat format)."""
    prompt = _text(row.get(col_map.get("prompt", "prompt"), ""))
    completion = _text(row.get(col_map.get("completion", "completion"), ""))
    if not prompt or not completion:
        return None
    return {"prompt": prompt, "completion": completion}


def to_eval(result):
    """A chat or flat result as an eval item {"prompt", "expected"}."""
    if result is None:
        return None
    if "messages" in result:
        msgs = result["messages"]
        prompt = next((m["content"] for m in msgs if m["role"] == "user"), "")
        expected = next((m["content"] for m in msgs if m["role"] == "assistant"), "")
        if not prompt or not expected:
            return None
        return {"prompt": prompt, "expected": expected}
    if "prompt" in result and "completion" in result:
        return {"prompt": result["prompt"], "expected": result["completion"]}
    return None


# -- loading -------------------------------------------------------------------

def _rows_from_jsonl(path):
    rows = []
    with open(path, "r", encoding="utf-8") as handle:
        for number, line in enumerate(handle, 1):
            line = line.strip()
            if not line:
                continue
            try:
                row = json.loads(line)
            except ValueError as exc:
                fail("%s line %d is not JSON: %s" % (path, number, exc))
            if isinstance(row, dict):
                rows.append(row)
    return rows


def _rows_from_json(path, split):
    with open(path, "r", encoding="utf-8") as handle:
        try:
            data = json.load(handle)
        except ValueError as exc:
            fail("%s is not JSON: %s" % (path, exc))
    if isinstance(data, dict):
        # {"train": [...], "test": [...]} picks the split; {"data": [...]}
        # and a columnar {"col": [...], ...} shape are both accepted. Lists
        # of objects are splits; lists of scalars are columns.
        lists = {k: v for k, v in data.items() if isinstance(v, list)}
        rows_shaped = any(any(isinstance(item, dict) for item in v) for v in lists.values())
        if split in lists and (rows_shaped or not lists[split]):
            data = lists[split]
        elif "data" in lists and not rows_shaped:
            data = lists["data"]
        elif "data" in lists and any(isinstance(item, dict) for item in lists["data"]):
            data = lists["data"]
        elif lists and len(lists) == len(data) and not rows_shaped:
            columns = list(lists.keys())
            length = min(len(v) for v in lists.values())
            data = [{c: lists[c][i] for c in columns} for i in range(length)]
        else:
            fail("split %r not found in %s. Available: %s" % (split, path, sorted(lists.keys())))
    if not isinstance(data, list):
        fail("%s must hold a JSON array of objects" % path)
    return [row for row in data if isinstance(row, dict)]


def _rows_from_csv(path):
    with open(path, "r", encoding="utf-8", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def _rows_from_parquet(files, split):
    try:
        from datasets import load_dataset
    except ImportError:
        fail("Parquet needs the 'datasets' library. Install it with: "
             "apogee train setup --with prepare")
    try:
        ds = load_dataset("parquet", data_files=files, split=split)
    except Exception as exc:  # the library raises its own family of errors
        fail("Failed to load %s: %s" % (", ".join(files), exc))
    return [dict(row) for row in ds]


def load_source(source, split):
    """Rows from a local file, or from every data file in a directory."""
    if os.path.isdir(source):
        for ext in ("parquet", "jsonl", "json", "csv"):
            files = sorted(
                os.path.join(source, f)
                for f in os.listdir(source)
                if f.endswith("." + ext)
            )
            if files:
                emit({"message": "Reading %d %s file(s) from %s" % (len(files), ext, source)})
                if ext == "parquet":
                    return _rows_from_parquet(files, split)
                rows = []
                for f in files:
                    rows.extend(_load_file(f, ext, split))
                return rows
        fail("No supported data files found in %r. Expected Parquet, JSON, JSONL "
             "or CSV files." % source)

    if os.path.isfile(source):
        ext = source.rsplit(".", 1)[-1].lower() if "." in source else ""
        if ext not in ("jsonl", "json", "parquet", "csv"):
            fail("Unsupported file extension %r. Supported: jsonl, json, parquet, csv" % ext)
        return _load_file(source, ext, split)

    fail("Source %r is not a file or directory" % source)


def _load_file(path, ext, split):
    if ext == "jsonl":
        return _rows_from_jsonl(path)
    if ext == "json":
        return _rows_from_json(path, split)
    if ext == "csv":
        return _rows_from_csv(path)
    return _rows_from_parquet([path], split)


# -- the row pipeline ----------------------------------------------------------

def process_rows(rows, fmt, col_map, flat, as_eval):
    """Yield output objects for every row, applying the format and col_map.

    OASST is handled specially: consecutive prompter->assistant rows are
    paired. Every other format converts each row independently.
    """
    if fmt == "oasst":
        role_col = col_map.get("role", "role")
        text_col = col_map.get("text", "text")
        role_map = {"prompter": "user", "assistant": "assistant", "user": "user"}
        pending_user = None
        for row in rows:
            role = role_map.get(str(row.get(role_col, "")), "")
            text = _text(row.get(text_col, ""))
            if not role or not text:
                continue
            if role == "user":
                pending_user = text
            elif role == "assistant" and pending_user is not None:
                if flat:
                    result = {"prompt": pending_user, "completion": text}
                else:
                    result = {"messages": [
                        {"role": "user", "content": pending_user},
                        {"role": "assistant", "content": text},
                    ]}
                pending_user = None
                if as_eval:
                    result = to_eval(result)
                if result:
                    yield result
        return

    if flat:
        makers = {
            "alpaca": make_flat_alpaca,
            "sharegpt": make_flat_sharegpt,
            "chatml": make_flat_sharegpt,
            "prompt-completion": make_flat_prompt_completion,
        }
    else:
        makers = {
            "alpaca": make_messages_alpaca,
            "sharegpt": make_messages_sharegpt,
            "chatml": make_messages_sharegpt,
            "prompt-completion": make_messages_prompt_completion,
        }

    make_fn = makers.get(fmt)
    if make_fn is None:
        fail("Unsupported format %r" % fmt)

    for row in rows:
        result = make_fn(row, col_map)
        if as_eval:
            result = to_eval(result)
        if result is not None:
            yield result


# -- main ----------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(description="Dataset preparation driver for Apogee")
    parser.add_argument("--source", required=True,
                        help="A local file (JSONL/JSON/CSV/Parquet) or a directory of them")
    parser.add_argument("--out", required=True, help="Output JSONL file path")
    parser.add_argument("--format", default="", dest="fmt",
                        choices=["alpaca", "sharegpt", "chatml", "oasst",
                                 "prompt-completion", ""],
                        help="Format preset (auto-detected when omitted)")
    parser.add_argument("--map", default="", dest="col_map_str",
                        help="Column renames: dest=src[,dest2=src2] "
                             "(e.g. prompt=question,completion=answer)")
    parser.add_argument("--split", default="train",
                        help="Dataset split to use (default: train)")
    parser.add_argument("--as-eval", action="store_true",
                        help="Emit the eval suite shape {prompt, expected}")
    parser.add_argument("--flat", action="store_true",
                        help="Emit {prompt, completion} instead of chat {messages}")
    args = parser.parse_args()

    col_map = {}
    if args.col_map_str:
        for pair in args.col_map_str.split(","):
            pair = pair.strip()
            if not pair:
                continue
            if "=" not in pair:
                fail("Invalid --map entry %r. Expected format: dest=src_column" % pair)
)PY",
    R"PY(            dest, src = pair.split("=", 1)
            col_map[dest.strip()] = src.strip()

    emit({"message": "Loading dataset from %s (split: %r)..." % (args.source, args.split)})
    rows = load_source(args.source, args.split)
    n_rows = len(rows)
    emit({"message": "Loaded %d rows" % n_rows})

    columns = []
    for row in rows[:100]:
        for key in row.keys():
            if key not in columns:
                columns.append(key)

    fmt = args.fmt
    if not fmt:
        fmt = detect_format(columns)
        if fmt:
            emit({"message": "Auto-detected format: %r" % fmt})
        else:
            col_list = ", ".join(repr(c) for c in columns)
            example = (
                "--map prompt=%s,completion=%s" % (columns[0], columns[1])
                if len(columns) >= 2
                else "--map prompt=<col>,completion=<col>"
            )
            fail("Cannot determine dataset format. Detected columns: %s\n"
                 "Specify a preset with --format or map columns with %s" % (col_list, example))

    out_dir = os.path.dirname(args.out)
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)

    rows_written = 0
    emit({"message": "Converting %d rows with format %r..." % (n_rows, fmt)})
    with open(args.out, "w", encoding="utf-8") as handle:
        for row in process_rows(rows, fmt, col_map, args.flat, args.as_eval):
            handle.write(json.dumps(row) + "\n")
            rows_written += 1
    rows_skipped = max(n_rows - rows_written, 0)

    emit({"message": "Wrote %d rows (%d skipped)" % (rows_written, rows_skipped)})
    emit({"rows_written": rows_written, "rows_skipped": rows_skipped, "out": args.out})


if __name__ == "__main__":
    main()
)PY",
}};

const std::string& script_prepare_dataset_py() {
    static const std::string text = join(kScriptPrepareDatasetPy);
    return text;
}

constexpr std::array<std::string_view, 1> kScriptTrainMlxPy{{
    R"PY(#!/usr/bin/env python3
"""MLX LoRA training driver for Apogee (Apple Silicon).

Runs under the Python environment Apogee owns (`apogee train setup --trainer
mlx`), never the system Python, and speaks the one line protocol every
shipped driver speaks -- one JSON object per line on stdout:

  {"iteration": N, "total_iters": N, "loss": F, "lr": F, "throughput": F}
  {"message": "..."}      a note
  {"error": "..."}        fatal; a non-zero exit follows
  {"fused_dir": "..."}    fuse's terminal record
  {"text": "..."}         infer's terminal record

Modes (--mode):
  train  LoRA fine-tune through `mlx_lm.lora` (the default)
  fuse   merge the adapter into the base model (`mlx_lm.fuse`) -> SafeTensors
  infer  generate one answer with the adapter, for eval scoring

Requires the `mlx` requirement set:  apogee train setup --trainer mlx

Two details, both found by reading mlx_lm:
`mlx_lm.lora --data` wants a DIRECTORY holding train.jsonl and valid.jsonl,
not a file (a file path fails with "training set not found"), so train mode
lays that directory out from the dataset; and `--mask-prompt` is accepted
and forwarded, since the orchestrator passes it.
"""

import argparse
import json
import os
import re
import subprocess
import sys
from pathlib import Path

# ── Protective environment variables ──────────────────────────────────────────
# Set before any ML import, and inherited by the mlx_lm subprocesses.
# KMP_DUPLICATE_LIB_OK: suppresses the OpenMP abort when two bundled libomp
#   copies (numpy/OpenBLAS and mlx's dependencies) load into one process.
# TOKENIZERS_PARALLELISM: keeps HuggingFace tokenizers from forking workers
#   that deadlock with multiprocessing on macOS.
os.environ.setdefault("KMP_DUPLICATE_LIB_OK", "TRUE")
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")

# Apogee never reaches the HuggingFace Hub from a driver: the base model is a
# local SafeTensors snapshot, and these make loading anything else fail
# loudly rather than download quietly.
os.environ["HF_HUB_OFFLINE"] = "1"
os.environ["TRANSFORMERS_OFFLINE"] = "1"
os.environ["HF_DATASETS_OFFLINE"] = "1"
os.environ["HF_HUB_DISABLE_TELEMETRY"] = "1"

# `Iter 10: Train loss 2.123, Learning Rate 1.000e-05, It/sec 2.345, ...`
# Newer mlx_lm prints no `/total`; the total then comes from --iters.
_ITER_RE = re.compile(
    r"Iter\s+(\d+)(?:/(\d+))?[:\s]+.*?[Ll]oss\s+([\d.]+)"
    r".*?[Ll]earning [Rr]ate\s+([\d.eE+\-]+)"
    r".*?It/sec\s+([\d.]+)",
)

MLX_DEFAULT_ITERS = 1000


def emit(obj):
    print(json.dumps(obj), flush=True)


def fail(message, code=1):
    emit({"error": message})
    sys.exit(code if code else 1)


def check_mlx():
    try:
        import mlx_lm  # noqa: F401
    except ImportError:
        fail(
            "mlx-lm is not installed in the training environment. "
            "Run: apogee train setup --trainer mlx"
        )


def lay_out_data_dir(dataset, data_dir):
    """mlx_lm.lora reads {train,valid}.jsonl from a directory.

    Every example trains; the validation set is a copy of the first tenth
    (at least one line), so mlx_lm's periodic validation has something to
    read without holding examples back from a small dataset. The number it
    reports is therefore in-sample -- the eval gate is the real check.
    """
    lines = [line for line in Path(dataset).read_text(encoding="utf-8").splitlines() if line.strip()]
    if not lines:
        fail(f"the dataset is empty: {dataset}")
    data_dir.mkdir(parents=True, exist_ok=True)
    (data_dir / "train.jsonl").write_text("\n".join(lines) + "\n", encoding="utf-8")
    valid = lines[: max(1, len(lines) // 10)]
    (data_dir / "valid.jsonl").write_text("\n".join(valid) + "\n", encoding="utf-8")
    return len(lines), len(valid)


def stream(cmd):
    """Runs cmd, yielding its output lines (stderr folded in: mlx_lm prints
    progress on stdout and warnings on stderr, and both are notes here; the
    driver's OWN stderr is what Apogee captures as the failure tail)."""
    proc = subprocess.Popen(
        cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace"
    )
    for line in proc.stdout:
        line = line.rstrip()
        if line:
            yield line
    proc.wait()
    if proc.returncode != 0:
        fail(f"{cmd[2]} exited with code {proc.returncode}", proc.returncode)


def run_train(args):
    check_mlx()
    if not args.dataset or not args.output_dir:
        fail("--dataset and --output-dir are required for train mode")
    data_dir = Path(args.data_dir) if args.data_dir else Path(args.output_dir).parent / "data"
    total, valid = lay_out_data_dir(args.dataset, data_dir)
    emit({"message": f"{total} training example(s); validation is a copy of the first {valid}"})
    if args.method == "qlora":
        emit({"message": "qlora on MLX: LoRA is applied to the snapshot as stored -- "
                         "a quantized snapshot trains as QLoRA, a full-precision one as LoRA"})

    cmd = [
        sys.executable, "-m", "mlx_lm.lora",
        "--model", args.model,
        "--train",
        "--data", str(data_dir),
        "--adapter-path", args.output_dir,
    ]
    if args.iters is not None:
        cmd += ["--iters", str(args.iters)]
    if args.batch_size is not None:
        cmd += ["--batch-size", str(args.batch_size)]
    if args.num_layers is not None:
        cmd += ["--num-layers", str(args.num_layers)]
    if args.grad_checkpoint:
        cmd.append("--grad-checkpoint")
    if args.mask_prompt:
        cmd.append("--mask-prompt")

    total_iters = args.iters if args.iters else MLX_DEFAULT_ITERS
    for line in stream(cmd):
        m = _ITER_RE.search(line)
        if m:
            emit({
                "iteration": int(m.group(1)),
                "total_iters": int(m.group(2)) if m.group(2) else total_iters,
                "loss": float(m.group(3)),
                "lr": float(m.group(4)),
                "throughput": float(m.group(5)),
            })
        else:
            emit({"message": line})
    emit({"message": f"adapter saved to {args.output_dir}"})


def run_fuse(args):
    check_mlx()
    if not args.adapter_path or not args.output_dir:
        fail("--adapter-path and --output-dir are required for fuse mode")
    emit({"message": f"fusing {args.adapter_path} into {args.model}"})
    cmd = [
        sys.executable, "-m", "mlx_lm.fuse",
        "--model", args.model,
        "--adapter-path", args.adapter_path,
        "--save-path", args.output_dir,
    ]
    for line in stream(cmd):
        emit({"message": line})
    emit({"fused_dir": args.output_dir})


def run_infer(args):
    check_mlx()
    if args.prompt is None:
        fail("--prompt is required for infer mode")
    from mlx_lm import load, generate

    # An empty adapter path is the untuned base: eval's pairwise baseline.
    model, tokenizer = load(args.model, adapter_path=args.adapter_path or None)
    prompt = args.prompt
    if getattr(tokenizer, "chat_template", None):
        prompt = tokenizer.apply_chat_template(
            [{"role": "user", "content": prompt}], add_generation_prompt=True, tokenize=False
        )
    text = generate(model, tokenizer, prompt=prompt, max_tokens=args.max_tokens, verbose=False)
    emit({"text": text.strip()})


def main():
    parser = argparse.ArgumentParser(description="MLX LoRA training driver for Apogee")
    parser.add_argument("--mode", default="train", choices=["train", "fuse", "infer"])
    parser.add_argument("--model", required=True, help="Local SafeTensors snapshot directory")
    parser.add_argument("--dataset", help="Path to .jsonl training data (train mode)")
    parser.add_argument("--data-dir", help="Where {train,valid}.jsonl are laid out (train mode)")
    parser.add_argument("--method", default="lora", choices=["lora", "qlora"])
    parser.add_argument("--output-dir", help="Adapter directory (train) or fused model (fuse)")
    parser.add_argument("--adapter-path", default="", help="Adapter directory (fuse/infer modes)")
    parser.add_argument("--iters", type=int, default=None)
    parser.add_argument("--batch-size", type=int, default=None)
    parser.add_argument("--num-layers", type=int, default=None)
    parser.add_argument("--grad-checkpoint", action="store_true")
    parser.add_argument("--mask-prompt", action="store_true",
                        help="Completion-only loss: the prompt tokens are excluded")
    parser.add_argument("--prompt", help="Prompt text (infer mode)")
    parser.add_argument("--max-tokens", type=int, default=256, help="Max new tokens (infer mode)")
    args = parser.parse_args()

    if args.mode == "train":
        run_train(args)
    elif args.mode == "fuse":
        run_fuse(args)
    else:
        run_infer(args)


if __name__ == "__main__":
    main()
)PY",
}};

const std::string& script_train_mlx_py() {
    static const std::string text = join(kScriptTrainMlxPy);
    return text;
}

constexpr std::array<std::string_view, 1> kScriptTrainPeftPy{{
    R"PY(#!/usr/bin/env python3
"""PEFT/CUDA training driver for Apogee.

Runs under the Python environment Apogee owns (`apogee train setup --trainer
peft`), never the system Python, and speaks the one line protocol every
shipped driver speaks -- one JSON object per line on stdout:

  {"iteration": N, "total_iters": N, "loss": F, "lr": F, "throughput": F}
  {"message": "..."}      a note
  {"error": "..."}        fatal; a non-zero exit follows
  {"fused_dir": "..."}    fuse's terminal record
  {"text": "..."}         infer's terminal record

Modes (--mode):
  train  LoRA / QLoRA fine-tune with transformers + peft (+ bitsandbytes)
  fuse   merge the adapter into the base model (merge_and_unload) -> SafeTensors
  infer  generate one answer with the adapter, for eval scoring

Requires the `peft` requirement set:  apogee train setup --trainer peft

The trainer is transformers' own `Trainer` over a tokenised dataset with the
prompt masked EXACTLY (the prompt's token count, from the chat template with
the generation prompt appended) rather than trl's SFTTrainer with the
response-template collator: that collator was
removed from trl, and the template heuristic it needed was a guess.
"""

import json
import os
import platform
import sys

# ── Apple Silicon guard ────────────────────────────────────────────────────────
# bitsandbytes requires NVIDIA CUDA. On macOS ARM it calls abort() (SIGABRT)
# inside its C-extension init when CUDA is absent -- which no try/except
# catches. So the guard runs BEFORE any other import. Apogee selects
# train_mlx.py on darwin/arm64; this script must not run there.
#
# APOGEE_TRAINING_STUB_MODULES is set only by the protocol test, which runs
# this script under stub `transformers`/`peft`/`torch` modules and never
# imports the real bitsandbytes -- it is what lets the emitter be proven on
# the one merge-blocking CI target, which is Apple Silicon.
if (
    sys.platform == "darwin"
    and platform.machine() == "arm64"
    and not os.environ.get("APOGEE_TRAINING_STUB_MODULES")
):
    print(json.dumps({"error": (
        "train_peft.py requires NVIDIA CUDA and is not supported on Apple Silicon. "
        "Run 'apogee train run' with --trainer mlx (auto selects it on macOS arm64)."
    )}), flush=True)
    sys.exit(1)

import argparse
from pathlib import Path

# ── Protective environment variables ──────────────────────────────────────────
# Must be set before any ML library import.
# KMP_DUPLICATE_LIB_OK: suppresses the OpenMP abort when PyTorch's bundled
#   libomp and another copy (numpy/OpenBLAS) are both loaded.
# TOKENIZERS_PARALLELISM: keeps HuggingFace tokenizers from forking workers
#   that deadlock with multiprocessing.
os.environ.setdefault("KMP_DUPLICATE_LIB_OK", "TRUE")
os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")

# Apogee never reaches the HuggingFace Hub from a driver: the base model is a
# local SafeTensors snapshot, and these make anything else fail loudly.
os.environ["HF_HUB_OFFLINE"] = "1"
os.environ["TRANSFORMERS_OFFLINE"] = "1"
os.environ["HF_DATASETS_OFFLINE"] = "1"
os.environ["HF_HUB_DISABLE_TELEMETRY"] = "1"

MAX_SEQUENCE_TOKENS = 2048
LORA_RANK = 16
LORA_ALPHA = 32
LORA_DROPOUT = 0.05
LEARNING_RATE = 2e-4
DEFAULT_ITERS = 1000
DEFAULT_BATCH = 4


def emit(obj):
    print(json.dumps(obj), flush=True)


def fail(message, code=1):
    emit({"error": message})
    sys.exit(code if code else 1)


def check_deps():
    missing = []
    for pkg in ["torch", "transformers", "peft", "bitsandbytes", "accelerate"]:
        try:
            __import__(pkg)
        except ImportError:
            missing.append(pkg)
    if missing:
        fail(
            f"missing Python packages in the training environment: {', '.join(missing)}. "
            "Run: apogee train setup --trainer peft"
        )


def read_records(dataset):
    records = []
    with open(dataset, encoding="utf-8") as f:
        for number, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as e:
                fail(f"{dataset}:{number}: not JSON ({e.msg})")
    if not records:
        fail(f"the dataset is empty: {dataset}")
    return records


def split_example(tokenizer, record):
    """The prompt text and the full text of one example.

    Chat lines go through the tokenizer's template -- the prompt is every
    message but the last assistant turn WITH the generation prompt appended,
    so its token count is exactly where the completion starts. Flat lines
    are `prompt` + `completion`.
    """
    if "messages" in record:
        messages = record["messages"]
        if not messages or messages[-1].get("role") != "assistant":
            return None
        prompt = tokenizer.apply_chat_template(
            messages[:-1], add_generation_prompt=True, tokenize=False
        )
        full = tokenizer.apply_chat_template(messages, tokenize=False)
        return prompt, full
    if "prompt" in record and "completion" in record:
        return record["prompt"], record["prompt"] + record["completion"]
    return None


def load_tokenizer(path):
    from transformers import AutoTokenizer

    tokenizer = AutoTokenizer.from_pretrained(path, trust_remote_code=True, local_files_only=True)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token
    return tokenizer


def load_base(path, quantized):
    import torch
    from transformers import AutoModelForCausalLM, BitsAndBytesConfig

    if quantized:
        return AutoModelForCausalLM.from_pretrained(
            path,
            quantization_config=BitsAndBytesConfig(
                load_in_4bit=True,
                bnb_4bit_quant_type="nf4",
                bnb_4bit_use_double_quant=True,
                bnb_4bit_compute_dtype=torch.bfloat16,
            ),
            device_map="auto",
            trust_remote_code=True,
            local_files_only=True,
        )
    return AutoModelForCausalLM.from_pretrained(
        path,
        device_map="auto",
        torch_dtype=torch.bfloat16,
        trust_remote_code=True,
        local_files_only=True,
    )


def run_train(args):
    check_deps()
    if not args.dataset or not args.output_dir:
        fail("--dataset and --output-dir are required for train mode")

    import torch
    from peft import LoraConfig, TaskType, get_peft_model
    from transformers import Trainer, TrainerCallback, TrainingArguments

    emit({"message": f"loading tokenizer and model from {args.model}"})
    tokenizer = load_tokenizer(args.model)
    quantized = args.method == "qlora"
    emit({"message": "loading model in 4-bit (QLoRA)" if quantized else "loading model (LoRA)"})
    model = load_base(args.model, quantized)

    lora = LoraConfig(
        r=LORA_RANK,
        lora_alpha=LORA_ALPHA,
        lora_dropout=LORA_DROPOUT,
        bias="none",
        task_type=TaskType.CAUSAL_LM,
        target_modules=args.target_modules.split(",") if args.target_modules else "all-linear",
    )
    model = get_peft_model(model, lora)
    if args.grad_checkpoint:
        model.enable_input_require_grads()
        model.gradient_checkpointing_enable()

    emit({"message": f"tokenising {args.dataset}"})
    examples = []
    skipped = 0
    for record in read_records(args.dataset):
        split = split_example(tokenizer, record)
        if split is None:
            skipped += 1
            continue
        prompt_text, full_text = split
        ids = tokenizer(full_text, truncation=True, max_length=MAX_SEQUENCE_TOKENS)["input_ids"]
        labels = list(ids)
        if args.mask_prompt:
            prompt_len = len(tokenizer(prompt_text, truncation=True,
                                       max_length=MAX_SEQUENCE_TOKENS)["input_ids"])
            for i in range(min(prompt_len, len(labels))):
                labels[i] = -100
        examples.append({"input_ids": ids, "labels": labels})
    if not examples:
        fail("no usable examples: each line needs `messages` ending in an assistant turn, "
             "or `prompt` and `completion`")
    if skipped:
        emit({"message": f"{skipped} line(s) skipped: no assistant turn or no prompt/completion"})
    emit({"message": f"{len(examples)} example(s)" +
          (" with the prompt masked out of the loss" if args.mask_prompt else "")})

    class ListDataset(torch.utils.data.Dataset):
        def __init__(self, rows):
            self.rows = rows

        def __len__(self):
            return len(self.rows)

        def __getitem__(self, index):
            return self.rows[index]

    pad_id = tokenizer.pad_token_id

    def collate(batch):
        width = max(len(row["input_ids"]) for row in batch)
        input_ids = [row["input_ids"] + [pad_id] * (width - len(row["input_ids"])) for row in batch]
        labels = [row["labels"] + [-100] * (width - len(row["labels"])) for row in batch]
        attention = [[1] * len(row["input_ids"]) + [0] * (width - len(row["input_ids"]))
                     for row in batch]
        return {
            "input_ids": torch.tensor(input_ids),
            "labels": torch.tensor(labels),
            "attention_mask": torch.tensor(attention),
        }

    steps = args.iters if args.iters else DEFAULT_ITERS
    batch = args.batch_size if args.batch_size else DEFAULT_BATCH
    os.makedirs(args.output_dir, exist_ok=True)
    bf16 = bool(torch.cuda.is_available() and torch.cuda.is_bf16_supported())
    training_args = TrainingArguments(
        output_dir=args.output_dir,
        max_steps=steps,
        per_device_train_batch_size=batch,
        gradient_accumulation_steps=1,
        learning_rate=LEARNING_RATE,
        bf16=bf16,
        fp16=not bf16 and torch.cuda.is_available(),
        logging_steps=1,
        save_strategy="no",
        report_to="none",
    )

    class Progress(TrainerCallback):
        def on_log(self, _args, state, _control, logs=None, **_kwargs):
            if logs and "loss" in logs:
                emit({
                    "iteration": int(state.global_step),
                    "total_iters": steps,
                    "loss": float(logs.get("loss", 0.0)),
                    "lr": float(logs.get("learning_rate", 0.0)),
                    "throughput": float(logs.get("train_steps_per_second", 0.0)),
                })

    emit({"message": f"training: {args.method}, {steps} step(s), batch {batch}"})
    trainer = Trainer(
        model=model,
        args=training_args,
        train_dataset=ListDataset(examples),
        data_collator=collate,
        callbacks=[Progress()],
    )
    trainer.train()

    emit({"message": f"saving adapter to {args.output_dir}"})
    trainer.model.save_pretrained(args.output_dir)
    tokenizer.save_pretrained(args.output_dir)
    emit({"message": "training complete"})


def run_fuse(args):
    check_deps()
    if not args.adapter_path or not args.output_dir:
        fail("--adapter-path and --output-dir are required for fuse mode")
    from peft import PeftModel

    emit({"message": f"loading base model {args.model}"})
    tokenizer = load_tokenizer(args.model)
    base = load_base(args.model, quantized=False)
    emit({"message": f"loading adapter from {args.adapter_path}"})
    model = PeftModel.from_pretrained(base, args.adapter_path, local_files_only=True)
    emit({"message": "merging the adapter into the base model (merge_and_unload)"})
    model = model.merge_and_unload()
    os.makedirs(args.output_dir, exist_ok=True)
    emit({"message": f"saving the fused model to {args.output_dir}"})
    model.save_pretrained(args.output_dir, safe_serialization=True)
    tokenizer.save_pretrained(args.output_dir)
    emit({"fused_dir": args.output_dir})


def run_infer(args):
    check_deps()
    if args.prompt is None:
        fail("--prompt is required for infer mode")
    import torch
    from peft import PeftModel

    tokenizer = load_tokenizer(args.model)
    model = load_base(args.model, quantized=False)
    # An empty adapter path is the untuned base: eval's pairwise baseline.
    if args.adapter_path:
        model = PeftModel.from_pretrained(model, args.adapter_path, local_files_only=True)
    model.eval()

    prompt = args.prompt
    if getattr(tokenizer, "chat_template", None):
        prompt = tokenizer.apply_chat_template(
            [{"role": "user", "content": prompt}], add_generation_prompt=True, tokenize=False
        )
    ids = tokenizer(prompt)["input_ids"]
    input_ids = torch.tensor([ids]).to(model.device)
    with torch.no_grad():
        out = model.generate(
            input_ids=input_ids,
            max_new_tokens=args.max_tokens,
            do_sample=False,
            pad_token_id=tokenizer.pad_token_id,
        )
    text = tokenizer.decode(out[0][len(ids):], skip_special_tokens=True)
    emit({"text": text.strip()})


def main():
    parser = argparse.ArgumentParser(description="PEFT/CUDA training driver for Apogee")
    parser.add_argument("--mode", default="train", choices=["train", "fuse", "infer"])
    parser.add_argument("--model", required=True, help="Local SafeTensors snapshot directory")
    parser.add_argument("--dataset", help="Path to .jsonl training data (train mode)")
    parser.add_argument("--data-dir", help="Accepted for symmetry with train_mlx.py; unused")
    parser.add_argument("--method", default="lora", choices=["lora", "qlora"])
    parser.add_argument("--output-dir", help="Adapter directory (train) or fused model (fuse)")
    parser.add_argument("--adapter-path", default="", help="Adapter directory (fuse/infer modes)")
    parser.add_argument("--iters", type=int, default=None, help=f"Training steps (default {DEFAULT_ITERS})")
    parser.add_argument("--batch-size", type=int, default=None, help=f"Per-device batch (default {DEFAULT_BATCH})")
    parser.add_argument("--num-layers", type=int, default=None,
                        help="Accepted for symmetry; PEFT targets modules, see --target-modules")
    parser.add_argument("--grad-checkpoint", action="store_true")
    parser.add_argument("--mask-prompt", action="store_true",
                        help="Completion-only loss: the prompt tokens are excluded")
    parser.add_argument("--target-modules", default=None,
                        help="Comma-separated LoRA target module names (default: all-linear)")
    parser.add_argument("--prompt", help="Prompt text (infer mode)")
    parser.add_argument("--max-tokens", type=int, default=256, help="Max new tokens (infer mode)")
    args = parser.parse_args()

    if args.mode == "train":
        run_train(args)
    elif args.mode == "fuse":
        run_fuse(args)
    else:
        run_infer(args)


if __name__ == "__main__":
    main()
)PY",
}};

const std::string& script_train_peft_py() {
    static const std::string text = join(kScriptTrainPeftPy);
    return text;
}

